import{_ as o,o as a,c as r,a3 as e}from"./chunks/framework.CqzWVxDX.js";const l="/ems_simulate/assets/sim-config-entry.CrC2pfvV.png",n="/ems_simulate/assets/sim-config-select.DaFM0U50.png",i="/ems_simulate/assets/sim-config-data.Doy3TNk0.png",b=JSON.parse('{"title":"测点配置（模拟配置）","description":"","frontmatter":{},"headers":[],"relativePath":"guide/simulation/point-config.md","filePath":"guide/simulation/point-config.md","lastUpdated":1787398325000}'),s={name:"guide/simulation/point-config.md"};function d(u,t,h,q,g,c){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="测点配置-模拟配置" tabindex="-1">测点配置（模拟配置） <a class="header-anchor" href="#测点配置-模拟配置" aria-label="Permalink to &quot;测点配置（模拟配置）&quot;">​</a></h1><h2 id="一、概述" tabindex="-1">一、概述 <a class="header-anchor" href="#一、概述" aria-label="Permalink to &quot;一、概述&quot;">​</a></h2><p><strong>测点配置</strong>（即&quot;模拟配置&quot;）用于配置<strong>哪些测点参与数据模拟</strong>，以及<strong>每个测点采用哪种模拟方式</strong>。它支持<strong>局部模拟</strong>：不再局限于全量模拟，可只对指定测点开启模拟，其余测点保持手动或映射驱动。</p><blockquote><p>模拟方式说明：</p><table tabindex="0"><thead><tr><th>模拟方式</th><th>说明</th></tr></thead><tbody><tr><td>无（None）</td><td>不参与模拟</td></tr><tr><td>定值（FixedValue）</td><td>持续保持配置的固定数值</td></tr><tr><td>随机（Random）</td><td>在上下限内随机跳变</td></tr><tr><td>自增（AutoIncrement）</td><td>按步长线性递增</td></tr><tr><td>自减（AutoDecrement）</td><td>按步长线性递减</td></tr><tr><td>正弦波（SineWave）</td><td>按正弦曲线波动</td></tr><tr><td>斜坡（Ramp）</td><td>按步长匀速变化</td></tr><tr><td>脉冲（Pulse）</td><td>按脉宽与间隔输出脉冲</td></tr></tbody></table></blockquote><h2 id="二、前置条件" tabindex="-1">二、前置条件 <a class="header-anchor" href="#二、前置条件" aria-label="Permalink to &quot;二、前置条件&quot;">​</a></h2><blockquote><p><strong>设备未开启时也可以进入「模拟配置」并提前保存配置；只有开始模拟时才需要先开启设备。</strong></p></blockquote><h3 id="开启条件说明" tabindex="-1">开启条件说明 <a class="header-anchor" href="#开启条件说明" aria-label="Permalink to &quot;开启条件说明&quot;">​</a></h3><table tabindex="0"><thead><tr><th>状态</th><th>模拟配置按钮</th></tr></thead><tbody><tr><td>设备<strong>未开启</strong></td><td>✅ 可配置，不能开始模拟</td></tr><tr><td>设备<strong>已开启</strong></td><td>✅ 可点击</td></tr><tr><td>客户端设备</td><td>❌ 不支持（模拟仅适用于服务端模拟设备）</td></tr><tr><td>IEC 61850 服务端未加载模型</td><td>❌ 需先导入/加载模型</td></tr></tbody></table><h3 id="操作步骤" tabindex="-1">操作步骤 <a class="header-anchor" href="#操作步骤" aria-label="Permalink to &quot;操作步骤&quot;">​</a></h3><ol><li>点击工具栏上的&quot;<strong>模拟配置</strong>&quot;按钮；</li><li>如需立即开始模拟，再开启设备并等待状态变为&quot;运行中&quot;。</li></ol><p><img src="'+l+'" alt=""></p><blockquote><p>工具栏上的&quot;模拟配置&quot;按钮不受设备启停状态限制。</p></blockquote><h2 id="三、配置模拟测点" tabindex="-1">三、配置模拟测点 <a class="header-anchor" href="#三、配置模拟测点" aria-label="Permalink to &quot;三、配置模拟测点&quot;">​</a></h2><p>打开&quot;模拟配置&quot;对话框后，在 <strong>页签 1：测点选择</strong> 中配置参与模拟的测点。</p><h3 id="步骤-1-选择测点" tabindex="-1">步骤 1：选择测点 <a class="header-anchor" href="#步骤-1-选择测点" aria-label="Permalink to &quot;步骤 1：选择测点&quot;">​</a></h3><ol><li><strong>左侧测点树</strong>：按分组树形展示设备全部测点；IEC 61850 设备按 DataModel 的 LD → LN 层级展示； <ul><li>支持关键字<strong>搜索</strong>测点；</li><li>支持<strong>分组级联勾选</strong>：勾选分组行 = 全选/全不选组内测点（含子分组）；</li></ul></li><li>点击中间&quot;<strong>&gt;&gt;</strong>&quot;按钮，将勾选的测点<strong>全部移入</strong>右侧&quot;已选测点&quot;列表；</li><li>右侧列表支持逐条&quot;<strong>×</strong>&quot;移出，或&quot;清空全部&quot;。</li></ol><p><img src="'+n+'" alt=""></p><blockquote><p>模拟配置 - 测点选择页签（左侧测点树 + 转移按钮 + 右侧已选测点）。</p></blockquote><h3 id="步骤-2-设置模拟方式" tabindex="-1">步骤 2：设置模拟方式 <a class="header-anchor" href="#步骤-2-设置模拟方式" aria-label="Permalink to &quot;步骤 2：设置模拟方式&quot;">​</a></h3><p>在右侧&quot;已选测点&quot;列表中，为每个测点设置：</p><ul><li><strong>模拟方式（模拟方式下拉）</strong>：无 / 定值 / 随机 / 自增 / 自减 / 正弦波 / 斜坡 / 脉冲；</li><li><strong>步长（Step）</strong>：数值变化步长（模拟方式为&quot;无&quot;或&quot;定值&quot;时步长不可用）；</li><li><strong>定值</strong>：选择&quot;定值模拟&quot;后填写，模拟运行时测点持续保持该数值。</li></ul><blockquote><p>💡 不同测点可设置不同的模拟方式，实现&quot;局部差异化模拟&quot;（如电压做正弦波模拟、电流做随机模拟）。</p></blockquote><h3 id="步骤-3-保存配置" tabindex="-1">步骤 3：保存配置 <a class="header-anchor" href="#步骤-3-保存配置" aria-label="Permalink to &quot;步骤 3：保存配置&quot;">​</a></h3><p>点击对话框底部&quot;保存&quot;，配置保存到本地。<strong>下次开启设备并启动模拟时，系统自动应用本次保存的测点模拟配置</strong>（未保存过则走默认全量模拟）。</p><h2 id="四、监视与启停模拟" tabindex="-1">四、监视与启停模拟 <a class="header-anchor" href="#四、监视与启停模拟" aria-label="Permalink to &quot;四、监视与启停模拟&quot;">​</a></h2><p>切换到 <strong>页签 2：模拟数据</strong>：</p><ul><li><strong>实时值监视</strong>：表格展示已选测点的当前值、模拟方式、步长等，支持<strong>自动刷新</strong>（可设间隔）与手动刷新；</li><li><strong>开始 / 停止模拟</strong>：点击&quot;开始模拟&quot;（或&quot;停止模拟&quot;）按钮，统一控制已选测点的模拟启停；</li><li>模拟运行期间，测点真实值按各自配置的方式持续变化。</li></ul><p><img src="'+i+'" alt=""></p><blockquote><p>模拟配置 - 模拟数据页签（实时值监视 + 自动刷新 + 开始/停止模拟）。</p></blockquote><h2 id="五、注意事项" tabindex="-1">五、注意事项 <a class="header-anchor" href="#五、注意事项" aria-label="Permalink to &quot;五、注意事项&quot;">​</a></h2><ul><li>模拟配置只对<strong>服务端（模拟）设备</strong>有效，客户端设备不支持；</li><li>模拟期间手动修改测点值、或对端通过协议写入，会与模拟值互相覆盖，以最后一次操作为准；</li><li>已保存的模拟配置在设备重启后仍会保留，再次开启设备模拟时自动应用；</li><li>模拟数据的监视与变化追踪、报文查看等能力见<a href="./data-monitor.html">数据监视</a>。</li></ul>',31)])])}const m=o(s,[["render",d]]);export{b as __pageData,m as default};
